// Apply the unified authoring decision without creating more issues or changing permanent IDs.
export function applyScope20261001(tasks, milestones) {
  const task = id => { const t = tasks.find(t => t.id === id); if (!t) throw Error(id); return t; };
  const update = (id, patch) => Object.assign(task(id), patch);
  Object.assign(milestones[0], {goal:'一个项目入口填写目标、上传发行人材料及可选原稿、保存补充要求；原始材料和目标知识 MD 直接交 worker 编制，保留修订版和清洁版。原稿可为同企业、母公司、子公司或相似业务企业，也可不上传。', gate:'按 UNIFIED-A01—09 验统一流程、真实编制及 Word；复用现有身份/上传/任务能力。没有历史稿、财务预提取或规则发布平台不构成启动前置，M1 成本由平台承担。'});
  Object.assign(milestones[1], {goal:'统一编制流程增加余额、充值、扣分及最小后台账务；复用 M1 的原稿/目标信息、企业关系、报告期和材料版本；不做余额现金退款或用户消费记录页。',gate:'M1 统一流程可用，真实支付及幂等结算通过；无原稿可计费，不新增计费问卷，不在本次批准新关系系数。'});
  for (const t of tasks) for (const key of ['title','scope','acceptance']) {
    const convert = s => s.replaceAll('两类自带稿','可选原稿的统一编制').replaceAll('两条自带稿路径','统一编制流程').replaceAll('两条路径','统一编制流程').replaceAll('表单末尾','原对话区改为').replaceAll('字段末尾','补充要求区').replaceAll('单行补充','补充要求区');
    t[key] = Array.isArray(t[key]) ? t[key].map(convert) : convert(t[key]);
  }
  update('M1-06',{scope:['同一表单收集目标发行人、市场/品种、目标年度及一期、发行安排；不先选择有/无历史稿','历史/参考稿选填，上传后填写原稿企业、关系、品种和报告期；与目标分开','原对话区改成补充要求区，保存和明确开始分开，无助手聊天'],acceptance:['五种原稿情况共用同一入口','源/目标独立且重开恢复；未完成草稿可保存','切换目标市场只清除不适用品种，不篡改原稿元数据']});
  update('M1-07',{scope:['一个可选历史/参考募集书上传区；同企业/母公司/子公司/相似业务企业均可，没有原稿也可编制','每份原稿绑定材料版本及手填企业关系、品种、报告期；发行人财务/业务材料独立','复用真实上传、保存、单文件重试和账号隔离，不增加独立预提取步骤'],acceptance:['无原稿不提示必须补历史/相似稿；已上传原稿填写必要信息','传输与保存真实，失败不丢其他材料，重复文件不污染源/目标','信息正确恢复、换稿不沿用错元数据；输入不触发执行或扣费']});
  update('M1-13',{title:'将原对话区改为募集书编制的补充要求',scope:['复用现有对话区域为可编辑补充要求，不要求移到表单末尾','保存后刷新/重登恢复；无助手回复、追问或消息意图执行','旧用户要求保留；开始时锁定准确版本，运行中修改用于下一次明确执行'],acceptance:['补充要求保存/恢复正确，失败不丢原文','输入开始/继续等字样不执行，只有明确开始创建任务','当前 run 不被后续编辑改变，旧用户要求来源可追溯']});
  update('M1-31',{title:'保存目标与可选原稿的品种、企业关系、报告期，供知识选择和 M2 计费',dependsOn:['M1-04','M1-07'],scope:['目标与每份原稿分开保存；关系为同企业/目标的母公司/目标的子公司/相似业务企业','无原稿保存空引用，不要求不存在的源信息；填写值为用户声明，绑定材料与信息版本','输出同一版本的知识选择与计费依据，M2 不重复问卷；变更使未执行估算失效'],acceptance:['五种原稿情况与目标均准确保存恢复，方向不倒置','知识以目标品种为主，DFI 按阶段和实际工具组合，不用源品种覆盖目标','跨企业年份不抵减本企业实际期间，无稿不是零工作量，不凭关系新造费率']});
  update('M1-28',{title:'在统一 worker 中支持非同企业参考稿和无原稿编制',dependsOn:['M1-12','M1-31'],scope:['有母/子/相似业务企业稿时参考结构，目标事实来自目标发行人材料','没有任何原稿时仍由目标知识 MD 和发行人材料编制，不依赖参考库','共用输入与任务入口；实际所用基线如实标明企业，不强制审核画像或财务预提取'],acceptance:['参考库关闭且无原稿时实际编制新稿','参考企业名称/财务/债务/评级不残留为目标事实','局部缺项准确标注；纯复制、空壳和虚构事实不能算完成']});
  task('M1-26').dependsOn=['M1-12','M1-31'];
  task('M1-26').scope.push('统一入口接收目标知识 MD、材料、可选原稿信息和补充要求；不以独立事实提取或规则发布平台为编制前置；与 M1-28 共用 worker');
  update('M1-29',{scope:['保留真实修订版和清洁版；有明确编辑基线时标明原企业/版本，接受修订应得到清洁版','无稿首稿如实说明无旧文对照，后续使用本项目上一版成果修订；PDF 重建说明限制','原件及旧成果保留，可授权下载后显示完成；不强制额外说明 DOCX、在线编辑器或复杂历史浏览器'],acceptance:['实际修订与清洁版一致，不用颜色或纯复制冒充实际更新','非同企业参考不冒充本企业旧稿；无稿首稿不虚构历史','Word 可打开且内容完整；下载不启动新模型调用，跨账号不能访问']});
  update('M1-30',{dependsOn:['M1-07','M1-12','M1-13','M1-26','M1-28','M1-29','M1-31'],scope:['五项交付：输入上传、知识 MD、worker、状态与 Word、部署完整验收；复用原负责人和基础组件','覆盖四种企业关系及无原稿，原/目标信息、要求与知识准确进入真实 AI 任务','部署记录真实版本及结果，#448 缺陷按原场景复测，不因需求文档合并关闭'],acceptance:['UNIFIED-A01—09 逐项通过；先确认真实更新/编制而不是零调用原文复制','同一入口无需库或预提取/事实审批；实际权限、输入和 Word 交付正确','可恢复查看任务和成果，保留真实模型/用量/错误与回滚记录']});
  task('M2-02').scope.push('同时消费原企业关系和明确无原稿状态；非同企业源期间不能抵减目标期间；关系定价映射缺失由 M2 明确，本次不新设系数');
  task('M2-04').scope=task('M2-04').scope.map(x=>x.replace('本企业历史稿与用户自带相似稿均接入相同付费闭环，不依赖库推荐；无自带稿不收费启动','有任一关系原稿及无原稿都接入同一付费闭环，按批准方案计费，不依赖参考库'));
}
